"use client"

/**
 * Clean-room collaboration thread.
 * Bubbles, a calendar block, and a voice note share one log.
 * The waveform is drawn from `peaks`. Playback is a local clock; onPlay tells the host.
 * The host appends messages. Spanish chrome is the default. `meta` is never read.
 */

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { CalendarDays, Pause, Play, Send } from "lucide-react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"
import {
  formatChatStamp,
  formatEventWhen,
  orderEntries,
  voiceClock,
  waveformLevels,
  withChatLabels,
  type ActivityChatEntry,
  type ActivityChatLabels,
  type ActivityChatPerson,
} from "@/lib/activity-chat"

export type ActivityChatClassNames = {
  log?: string
  bubble?: string
  event?: string
  voice?: string
  composer?: string
}

export type ActivityChatProps<TMeta = Record<string, unknown>> = {
  messages: readonly ActivityChatEntry<TMeta>[]
  people?: readonly ActivityChatPerson[]
  currentUserId?: string
  onSend?: (body: string) => void
  onPlay?: (id: string) => void
  locale?: string
  timeZone?: string
  labels?: Partial<ActivityChatLabels>
  loading?: boolean
  error?: string | null
  onRetry?: () => void
  disabled?: boolean
  className?: string
  classNames?: ActivityChatClassNames
}

const subscribe = () => () => {}
const BARS = 28

function useReducedFlag() {
  const hydrated = React.useSyncExternalStore(subscribe, () => true, () => false)
  return !!useReducedMotion() && hydrated
}

function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (!parts.length) return "?"
  const first = parts[0]?.[0] ?? ""
  const last = parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : ""
  return `${first}${last}`.toLocaleUpperCase("es-MX")
}

export function ActivityChat<TMeta = Record<string, unknown>>({
  messages,
  people = [],
  currentUserId,
  onSend,
  onPlay,
  locale = "es-MX",
  timeZone = "America/Mexico_City",
  labels,
  loading = false,
  error = null,
  onRetry,
  disabled = false,
  className,
  classNames,
}: ActivityChatProps<TMeta>) {
  const copy = withChatLabels(labels)
  const reduced = useReducedFlag()
  const [draft, setDraft] = React.useState("")
  const [playingId, setPlayingId] = React.useState<string | null>(null)
  const [progress, setProgress] = React.useState(0)
  const logRef = React.useRef<HTMLDivElement>(null)
  const peopleById = React.useMemo(() => new Map(people.map((person) => [person.id, person])), [people])
  const ordered = React.useMemo(() => orderEntries(messages), [messages])

  React.useEffect(() => {
    const node = logRef.current
    if (!node) return
    if (typeof node.scrollTo === "function") {
      node.scrollTo({ top: node.scrollHeight, behavior: reduced ? "auto" : "smooth" })
    } else {
      node.scrollTop = node.scrollHeight
    }
  }, [ordered, reduced])

  const duration = Math.max(400, ordered.find((item) => item.id === playingId)?.voice?.durationMs ?? 1000)

  React.useEffect(() => {
    if (!playingId) return
    const started = performance.now()
    const timer = window.setInterval(() => {
      const next = Math.min(1, (performance.now() - started) / duration)
      setProgress(next)
      if (next >= 1) {
        window.clearInterval(timer)
        setPlayingId(null)
        setProgress(0)
      }
    }, 80)
    return () => window.clearInterval(timer)
  }, [playingId, duration])

  function authorName(authorId: string) {
    if (authorId === currentUserId) return copy.you
    return peopleById.get(authorId)?.name ?? copy.unknownAuthor
  }

  function toggleVoice(id: string) {
    if (disabled) return
    if (playingId === id) {
      setPlayingId(null)
      setProgress(0)
      return
    }
    setProgress(0)
    setPlayingId(id)
    onPlay?.(id)
  }

  function send() {
    const body = draft.trim()
    if (!body || disabled || !onSend) return
    onSend(body)
    setDraft("")
  }

  return (
    <section
      data-slot="activity-chat"
      data-disabled={disabled ? "true" : "false"}
      data-reduced-motion={reduced ? "true" : "false"}
      aria-label={copy.heading}
      className={cn("flex h-full min-h-0 min-w-0 flex-col gap-3 text-foreground", className)}
    >
      {disabled ? <p className="text-xs text-muted-foreground">{copy.disabledNote}</p> : null}
      {error ? (
        <div role="alert" className="flex flex-col items-start gap-2 rounded-lg border border-border p-3">
          <p className="text-sm font-medium">{copy.errorTitle}</p>
          <p className="text-sm text-muted-foreground break-words [overflow-wrap:anywhere]">{error}</p>
          {onRetry ? (
            <Button type="button" size="sm" variant="outline" onClick={onRetry}>
              {copy.retry}
            </Button>
          ) : null}
        </div>
      ) : null}
      <div
        ref={logRef}
        role="log"
        aria-live="polite"
        aria-relevant="additions"
        aria-busy={loading || undefined}
        className={cn("flex min-h-48 flex-1 flex-col gap-3 overflow-y-auto rounded-lg border border-border bg-background p-3", classNames?.log)}
      >
        {loading ? (
          <div className="flex flex-col gap-2">
            <span className="sr-only">{copy.loading}</span>
            <Skeleton className="h-12 w-2/3" />
            <Skeleton className="ml-auto h-12 w-1/2" />
            <Skeleton className="h-16 w-full" />
          </div>
        ) : ordered.length === 0 ? (
          <Empty>
            <EmptyHeader>
              <EmptyTitle>{copy.emptyTitle}</EmptyTitle>
              <EmptyDescription>{copy.emptyHint}</EmptyDescription>
            </EmptyHeader>
          </Empty>
        ) : (
          ordered.map((entry) => {
            const mine = entry.authorId === currentUserId
            const name = authorName(entry.authorId)
            const when = formatChatStamp(entry.createdAt, locale, timeZone)
            return (
              <motion.article
                key={entry.id}
                data-kind={entry.kind}
                data-own={mine ? "true" : "false"}
                initial={reduced ? false : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: reduced ? 0 : motionPresets.duration.fast, ease: motionPresets.ease.enter }}
                aria-label={copy.messageFrom(name, when)}
                className={cn("flex min-w-0 gap-2", mine && entry.kind === "message" && "flex-row-reverse")}
              >
                {entry.kind === "event" ? null : (
                  <Avatar size="sm">
                    <AvatarFallback>{initials(name)}</AvatarFallback>
                  </Avatar>
                )}
                <div className={cn("flex min-w-0 flex-col gap-1", mine && entry.kind === "message" ? "items-end" : "items-start", entry.kind === "event" && "w-full items-stretch")}>
                  <p className="text-xs text-muted-foreground">
                    <span>{name}</span>
                    <span aria-hidden="true"> · </span>
                    <time dateTime={entry.createdAt}>{when}</time>
                  </p>
                  {entry.kind === "event" && entry.event ? (
                    <div className={cn("flex w-full min-w-0 flex-col gap-1 rounded-lg border border-border bg-card p-3 shadow-sm", classNames?.event)}>
                      <p className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                        <CalendarDays aria-hidden="true" className="size-3.5" />
                        {copy.event}
                      </p>
                      <h3 className="text-sm font-medium break-words [overflow-wrap:anywhere]">{entry.event.title}</h3>
                      <p className="text-sm tabular-nums">{formatEventWhen(entry.event, locale, timeZone)}</p>
                      {entry.event.location ? <p className="text-sm text-muted-foreground break-words [overflow-wrap:anywhere]">{entry.event.location}</p> : null}
                    </div>
                  ) : null}
                  {entry.kind === "voice" && entry.voice ? (
                    <div className={cn("flex w-full max-w-sm min-w-0 items-center gap-2 rounded-lg bg-muted px-2 py-2 text-foreground", classNames?.voice)}>
                      <button
                        type="button"
                        disabled={disabled}
                        aria-pressed={playingId === entry.id}
                        aria-label={playingId === entry.id ? copy.pauseVoice(name) : copy.playVoice(name)}
                        className="inline-flex size-8 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground outline-none focus-visible:ring-3 focus-visible:ring-ring"
                        onClick={() => toggleVoice(entry.id)}
                      >
                        {playingId === entry.id ? <Pause aria-hidden="true" className="size-3.5" /> : <Play aria-hidden="true" className="size-3.5" />}
                      </button>
                      <div className="flex h-8 min-w-0 flex-1 items-center gap-0.5" aria-hidden="true">
                        {waveformLevels(entry.voice.peaks, BARS).map((level, index) => {
                          const played = playingId === entry.id && index / BARS < progress
                          return (
                            <span
                              key={`${entry.id}-${index}`}
                              className={cn("w-0.5 rounded-full", played ? "bg-primary" : "bg-foreground/35")}
                              style={{ height: `${Math.round(level * 100)}%` }}
                            />
                          )
                        })}
                      </div>
                      <span className="text-xs tabular-nums text-muted-foreground">
                        {voiceClock(playingId === entry.id ? progress * entry.voice.durationMs : entry.voice.durationMs)}
                      </span>
                      <span className="sr-only">{copy.voiceNote}</span>
                    </div>
                  ) : null}
                  {entry.kind === "message" ? (
                    <p
                      className={cn(
                        "max-w-[85%] rounded-lg px-3 py-2 text-sm break-words [overflow-wrap:anywhere]",
                        mine ? "bg-primary text-primary-foreground" : "bg-muted text-foreground",
                        classNames?.bubble,
                      )}
                    >
                      {entry.body}
                    </p>
                  ) : null}
                  {entry.kind === "voice" && entry.voice?.transcript ? (
                    <p className="max-w-sm text-xs text-muted-foreground break-words [overflow-wrap:anywhere]">{entry.voice.transcript}</p>
                  ) : null}
                </div>
              </motion.article>
            )
          })
        )}
      </div>
      <form
        className={cn("flex items-end gap-2", classNames?.composer)}
        onSubmit={(event) => {
          event.preventDefault()
          send()
        }}
      >
        <Textarea
          value={draft}
          disabled={disabled || !onSend}
          aria-label={copy.composer}
          placeholder={copy.composerPlaceholder}
          rows={2}
          className="min-h-16 min-w-0 flex-1"
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && !event.shiftKey) {
              event.preventDefault()
              send()
            }
          }}
        />
        <Button type="submit" disabled={disabled || !onSend || draft.trim().length === 0}>
          <Send aria-hidden="true" data-icon="inline-start" />
          {copy.send}
        </Button>
      </form>
    </section>
  )
}

/**
 * Clean-room model for a collaboration thread.
 * Messages, calendar blocks, and voice notes share one list.
 * The waveform is resampled from caller data. There is no audio file.
 * `TMeta` is never read. Chrome defaults to Spanish.
 */

export const CHAT_KINDS = ["message", "event", "voice"] as const

export type ActivityChatKind = (typeof CHAT_KINDS)[number]

export type ActivityChatPerson = {
  id: string
  name: string
}

export type ActivityChatEvent = {
  title: string
  startsAt: string
  endsAt: string
  location?: string
}

export type ActivityChatVoice = {
  durationMs: number
  peaks: readonly number[]
  transcript?: string
}

export type ActivityChatEntry<TMeta = Record<string, unknown>> = {
  id: string
  kind: ActivityChatKind
  authorId: string
  createdAt: string
  body?: string
  event?: ActivityChatEvent
  voice?: ActivityChatVoice
  /** Host payload. The thread never reads it. */
  meta?: TMeta
}

export type ActivityChatLabels = {
  heading: string
  emptyTitle: string
  emptyHint: string
  loading: string
  errorTitle: string
  retry: string
  disabledNote: string
  composer: string
  composerPlaceholder: string
  send: string
  voiceNote: string
  event: string
  unknownAuthor: string
  you: string
  playVoice: (name: string) => string
  pauseVoice: (name: string) => string
  messageFrom: (name: string, when: string) => string
}

export const activityChatLabels: ActivityChatLabels = {
  heading: "Conversación",
  emptyTitle: "Todavía no hay mensajes",
  emptyHint: "Escribe abajo para empezar.",
  loading: "Cargando la conversación",
  errorTitle: "No se pudo mostrar la conversación",
  retry: "Reintentar",
  disabledNote: "La conversación está deshabilitada",
  composer: "Mensaje",
  composerPlaceholder: "Escribe un mensaje",
  send: "Enviar",
  voiceNote: "Nota de voz",
  event: "Evento",
  unknownAuthor: "Alguien",
  you: "Tú",
  playVoice: (name) => `Reproducir nota de ${name}`,
  pauseVoice: (name) => `Pausar nota de ${name}`,
  messageFrom: (name, when) => `${name}, ${when}`,
}

export const activityChatLabelsEn: ActivityChatLabels = {
  heading: "Conversation",
  emptyTitle: "No messages yet",
  emptyHint: "Write below to start.",
  loading: "Loading the conversation",
  errorTitle: "The conversation could not be shown",
  retry: "Try again",
  disabledNote: "The conversation is disabled",
  composer: "Message",
  composerPlaceholder: "Write a message",
  send: "Send",
  voiceNote: "Voice note",
  event: "Event",
  unknownAuthor: "Someone",
  you: "You",
  playVoice: (name) => `Play note from ${name}`,
  pauseVoice: (name) => `Pause note from ${name}`,
  messageFrom: (name, when) => `${name}, ${when}`,
}

export function withChatLabels(labels?: Partial<ActivityChatLabels>): ActivityChatLabels {
  return { ...activityChatLabels, ...labels }
}

export function orderEntries<T extends { createdAt: string }>(entries: readonly T[]): T[] {
  return entries
    .map((entry, index) => ({ entry, index }))
    .sort((a, b) => {
      const aTime = Date.parse(a.entry.createdAt)
      const bTime = Date.parse(b.entry.createdAt)
      const aOk = Number.isFinite(aTime)
      const bOk = Number.isFinite(bTime)
      if (!aOk && !bOk) return a.index - b.index
      if (!aOk) return 1
      if (!bOk) return -1
      if (aTime === bTime) return a.index - b.index
      return aTime - bTime
    })
    .map(({ entry }) => entry)
}

export function voiceClock(ms: number) {
  const total = Math.max(0, Math.round((Number.isFinite(ms) ? ms : 0) / 1000))
  const minutes = Math.floor(total / 60)
  const seconds = total % 60
  return `${minutes}:${String(seconds).padStart(2, "0")}`
}

function clampPeak(value: number) {
  if (!Number.isFinite(value)) return 0.2
  return Math.min(1, Math.max(0.08, value))
}

/** Resample caller peaks into a fixed bar count. Missing data stays a quiet line. */
export function waveformLevels(peaks: readonly number[] | undefined, count: number) {
  const safe = Math.max(1, Math.round(count))
  if (!peaks?.length) return Array.from({ length: safe }, () => 0.2)
  if (peaks.length === safe) return peaks.map((value) => clampPeak(value))
  return Array.from({ length: safe }, (_, index) => {
    const position = safe === 1 ? 0 : (index / (safe - 1)) * (peaks.length - 1)
    const left = Math.floor(position)
    const right = Math.min(peaks.length - 1, left + 1)
    const mix = position - left
    return clampPeak((peaks[left] ?? 0) * (1 - mix) + (peaks[right] ?? 0) * mix)
  })
}

export function formatChatStamp(iso: string, locale: string, timeZone: string) {
  const parsed = Date.parse(iso)
  if (!Number.isFinite(parsed)) return iso
  return new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    timeZone,
  }).format(parsed)
}

export function formatEventWhen(event: ActivityChatEvent, locale: string, timeZone: string) {
  const start = Date.parse(event.startsAt)
  const end = Date.parse(event.endsAt)
  if (!Number.isFinite(start)) return event.startsAt
  const date = new Intl.DateTimeFormat(locale, {
    weekday: "short",
    day: "numeric",
    month: "short",
    timeZone,
  }).format(start)
  const time = new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit", timeZone }).format(start)
  if (!Number.isFinite(end)) return `${date} · ${time}`
  const endTime = new Intl.DateTimeFormat(locale, { hour: "2-digit", minute: "2-digit", timeZone }).format(end)
  return `${date} · ${time}–${endTime}`
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
